// Real alerts client (Phase 5 frontend integration).
//
// Tries the FastAPI backend's `/alerts/*` endpoints first — real bulletins
// generated by the automated alert-generation pipeline
// (backend/app/services/alert_service.py) from the real risk engine and,
// where validated, the real ML predictions — falling back to the
// deterministic mock feed in `src/data/alertsData.js` on any backend
// failure, same backend-first/short-timeout/visible-warning contract as
// weatherService.js and riskService.js. Every adapted alert carries a
// `source` field (`"rule-based-v1"` | `"ml-v1"` | `"combined"` for real
// alerts, `"simulated"` for the mock fallback).
import { mockRequest, BACKEND_ENABLED, fetchBackendJson, postBackendJson, warnFallback } from "./apiClient";
import { ALERTS, getActiveAlerts, getAlertById, getAlertsCountInRange } from "../data/alertsData";

function adaptAlert(a) {
  return {
    id: a.id,
    title: a.title,
    severity: a.severity,
    location: a.location,
    issuedAt: a.issuedAt,
    expiresAt: a.expiresAt,
    status: a.status,
    hazardType: a.hazardType,
    riskScore: a.riskScore,
    description: a.description,
    recommendedAction: a.recommendedAction,
    affectedGrids: [a.gridCellId],
    confidence: a.confidence != null ? Math.round(a.confidence * 100) : null,
    evidence: a.evidence,
    source: a.source,
    acknowledged: a.acknowledged,
  };
}

// GET /alerts
export async function fetchAllAlerts() {
  if (BACKEND_ENABLED) {
    try {
      const [active, history] = await Promise.all([
        fetchBackendJson("/alerts/active"),
        fetchBackendJson("/alerts/history"),
      ]);
      return [...active, ...history].map(adaptAlert);
    } catch (err) {
      warnFallback("all alerts", err);
    }
  }
  return mockRequest(() => ALERTS);
}

// GET /alerts/active
export async function fetchActiveAlerts() {
  if (BACKEND_ENABLED) {
    try {
      const alerts = await fetchBackendJson("/alerts/active");
      return alerts.map(adaptAlert);
    } catch (err) {
      warnFallback("active alerts", err);
    }
  }
  return mockRequest(() => getActiveAlerts());
}

// GET /alerts/history — resolved + expired, most recently concluded first.
export async function fetchAlertHistory() {
  if (BACKEND_ENABLED) {
    try {
      const alerts = await fetchBackendJson("/alerts/history");
      return alerts.map(adaptAlert);
    } catch (err) {
      warnFallback("alert history", err);
    }
  }
  return mockRequest(() => ALERTS.filter((a) => a.status === "resolved"));
}

// GET /alerts/:id
export async function fetchAlertById(id) {
  if (BACKEND_ENABLED) {
    try {
      const alert = await fetchBackendJson(`/alerts/${id}`);
      return adaptAlert(alert);
    } catch (err) {
      warnFallback(`alert ${id}`, err);
    }
  }
  return mockRequest(() => getAlertById(id));
}

// GET /alerts/count?range=...
// No real equivalent endpoint yet — kept as a mock-only helper for the
// Analytics page's alert-count-in-range widget.
export function fetchAlertsCountInRange(rangeKey) {
  return mockRequest(() => getAlertsCountInRange(rangeKey));
}

// POST /alerts/:id/acknowledge
export async function acknowledgeAlert(id) {
  if (BACKEND_ENABLED) {
    try {
      const alert = await postBackendJson(`/alerts/${id}/acknowledge`);
      return adaptAlert(alert);
    } catch (err) {
      warnFallback(`acknowledge alert ${id}`, err);
    }
  }
  return null;
}

// POST /alerts/:id/resolve
export async function resolveAlert(id) {
  if (BACKEND_ENABLED) {
    try {
      const alert = await postBackendJson(`/alerts/${id}/resolve`);
      return adaptAlert(alert);
    } catch (err) {
      warnFallback(`resolve alert ${id}`, err);
    }
  }
  return null;
}
